$r=runAyo('Add Later company',[['operation'=>'ayo.company.save','arguments'=>['name'=>'Later']]]);$os->mutate($os->read()['version'],'company.save',['name'=>'Manual'],'owner:1');denied(fn()=>LifeCommands::undo($store,$ai,$r['version'],$r['receipt']['id']),409);
