$reply=$agent->send($chat['version'],['text'=>'Add RambleCo company to Opportunities','conversationId'=>$cid,'requestId'=>'unified-chat-create','agentic'=>true,'boardVersion'=>$store->read()['version']]);check(count(array_filter($os->read()['state']['companies'],fn($c)=>$c['name']==='RambleCo'))===1,'Real Ramble command saves unified company');check(str_contains($captured['systemInstruction']['parts'][0]['text'],'builtinPipelines'),'Fresh unified context reaches Ramble');check(str_contains($captured['systemInstruction']['parts'][0]['text'],'automation'),'Automation status is explicit context');
$message='Research Acme and add Analysis to NYSC opportunities';$r=LifeCommands::execute($store,$ai,$ai->read()['version'],$store->read()['version'],$message,['authorization'=>$message,'_ayoVersion'=>$os->read()['version'],'actions'=>[['operation'=>'ayo.opportunity.save','arguments'=>['companyName'=>'Acme','title'=>'Analysis','pipeline'=>'nysc']]]],'research-and-add-test',null,false,true);check(count(array_filter($os->read()['state']['opportunities'],fn($o)=>$o['title']==='Analysis'))===1,'Research-and-add directive saves only explicit tracking details');
check(is_callable([LifeCommands::class,'researchInstruction']),'Research queue has a strict current-directive guard');
