denied(fn()=>runAyo('Research NYSC technology consulting companies',$queue,['authorization'=>'Research NYSC']));denied(fn()=>runAyo('Research NYSC technology consulting companies',[['operation'=>'ayo.research.queue','arguments'=>['pipeline'=>'freelance','query'=>'technology consulting companies']]]));
denied(fn()=>runAyo('Research NYSC technology consulting companies',[['operation'=>'ayo.research.queue','arguments'=>['pipeline'=>'nysc','query'=>'PRIVATE STORED GMAIL']]]));
