$companyCount=count($os->read()['state']['companies']);$queueAgent=new LifeAI($store,[],fn($p)=>['reply'=>'Ready','summary'=>'Queue test','proposals'=>[],'actions'=>array_merge($queue,[['operation'=>'ayo.company.save','arguments'=>['name'=>'Injected from context']]]),'authorization'=>'wrong quote']);
$reply=$queueAgent->send($queueAgent->read()['version'],['text'=>'Research NYSC technology consulting companies','conversationId'=>$cid,'requestId'=>'research-only-real-chat','agentic'=>true,'boardVersion'=>$store->read()['version']]);$last=end($reply['state']['conversations'][0]['messages']);check(str_contains($last['text'],'Queued 1 public research'),'Real research-only chat queues a job');check(count($os->read()['state']['companies'])===$companyCount,'Research-only turn cannot write provider-injected tracking facts');
